+<script>
+"use strict";
+
+const T_IGNITE = 1.5;
+const T_LIFTOFF = 4;
+const T_EXIT = 7;
+const T_RETURN = 12;
+const T_LAND = 17;
+const CYCLE = 18.2;
+
+const canvas = document.getElementById("c");
+const ctx = canvas.getContext("2d", { alpha: false });
+
+let W = 1, H = 1, dpr = 1;
+let skyCanvas, skyCtx, vignette;
+
+const SMOKE_N = 460;
+const EMBER_N = 140;
+const smoke = [];
+const embers = [];
+const puffs = [];
+let emberSprite;
+const ripples = [];
+let stars = [];
+let birds = [];
+
+let smokeAcc = 0;
+let trailAcc = 0;
+let emberAcc = 0;
+let ventAcc = 0;
+let rippleAcc = 0;
+let prevT = 0;
+let hazeBuf, hazeCtx;
+
+const CLOUDS = [
+  { x: 0.08, y: 0.16, s: 1.15, a: 0.22, tint: "186,204,226", spd: 6 },
+  { x: 0.62, y: 0.12, s: 0.95, a: 0.18, tint: "176,196,220", spd: 4.2 },
+  { x: 0.34, y: 0.24, s: 1.35, a: 0.14, tint: "206,214,230", spd: 3.4 },
+  { x: 0.84, y: 0.30, s: 1.05, a: 0.2, tint: "255,210,188", spd: 5.1 },
+  { x: 0.18, y: 0.40, s: 1.45, a: 0.22, tint: "255,190,164", spd: 3.8 },
+  { x: 0.52, y: 0.47, s: 1.2, a: 0.16, tint: "255,176,150", spd: 4.6 },
+  { x: 0.9, y: 0.2, s: 0.8, a: 0.15, tint: "198,208,226", spd: 7 }
+];
+
+function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
+function lerp(a, b, u) { return a + (b - a) * u; }
+function easeInOutCubic(u) {
+  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
+}
+function hash(n) {
+  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
+  return x - Math.floor(x);
+}
+function noise(t) {
+  const i = Math.floor(t);
+  const f = t - i;
+  const u = f * f * (3 - 2 * f);
+  return hash(i) + (hash(i + 1) - hash(i)) * u;
+}
+
+function altitude(t, exitAlt) {
+  if (t < T_IGNITE) return 0;
+  if (t < T_LIFTOFF) {
+    const u = (t - T_IGNITE) / (T_LIFTOFF - T_IGNITE);
+    return Math.pow(u, 2.25) * exitAlt * 0.2;
+  }
+  if (t < T_EXIT) {
+    const u = (t - T_LIFTOFF) / (T_EXIT - T_LIFTOFF);
+    const a0 = exitAlt * 0.2;
+    return a0 + (exitAlt - a0) * Math.pow(u, 1.72);
+  }
+  if (t < T_RETURN) return exitAlt;
+  if (t < T_LAND) {
+    const u = (t - T_RETURN) / (T_LAND - T_RETURN);
+    return exitAlt * (1 - easeInOutCubic(u));
+  }
+  return 0;
+}
+
+function animScale(t, alt, exitAlt) {
+  if (t >= T_RETURN && t < T_LAND) {
+    const u = (t - T_RETURN) / (T_LAND - T_RETURN);
+    return lerp(0.8, 1, easeInOutCubic(u));
+  }
+  if (t >= T_LAND || t < T_IGNITE) return 1;
+  const k = clamp(alt / exitAlt, 0, 1);
+  return 1 - 0.2 * Math.pow(k, 1.05);
+}
+
+function xDrift(t) {
+  if (t < T_RETURN || t >= T_LAND) return 0;
+  const u = (t - T_RETURN) / (T_LAND - T_RETURN);
+  return Math.sin(u * Math.PI) * Math.sin(u * Math.PI * 2) * 16;
+}
+
+function thrustLevel(t, time) {
+  if (t < 0.32 || t >= T_EXIT) return 0;
+  let base;
+  if (t < 1.15) base = (t - 0.32) / 0.83;
+  else if (t < 6.35) base = 1;
+  else base = 1 - (t - 6.35) / (T_EXIT - 6.35);
+  const flick = 0.84 + 0.16 * noise(time * 26.0 + 3.2);
+  return clamp(base, 0, 1) * flick;
+}
+
+function shakeAmt(t) {
+  if (t < 0.28 || t >= T_EXIT) return 0;
+  if (t < T_IGNITE) return ((t - 0.28) / (T_IGNITE - 0.28)) * 4.2;
+  if (t < 5.4) return 6.4 * (1 - (t - T_IGNITE) / 5.6);
+  return 2.1 * (1 - (t - 5.4) / (T_EXIT - 5.4));
+}
+
+function seaEnergy(t) {
+  if (t < 0.4) return 0;
+  if (t < 1.4) return (t - 0.4);
+  if (t < 6.2) return 1;
+  if (t < 9.2) return 1 - (t - 6.2) / 3;
+  return 0;
+}
+
+function padGlowAmt(t) {
+  if (t < 0.32) return 0;
+  if (t < T_IGNITE) return (t - 0.32) / (T_IGNITE - 0.32);
+  if (t < 5.2) return 1 - ((t - T_IGNITE) / 3.7) * 0.78;
+  if (t < 6.6) return 0.22 * (1 - (t - 5.2) / 1.4);
+  return 0;
+}
+
+function scorchAmt(t) {
+  if (t < 0.5) return 0;
+  if (t < 2.1) return (t - 0.5) / 1.6;
+  if (t < 8) return 1;
+  if (t < 12) return 1 - (t - 8) / 4;
+  return 0;
+}
+
+function armAngle(t) {
+  if (t < 1.32) return -0.06;
+  if (t < 2.05) return lerp(-0.06, -1.35, easeInOutCubic((t - 1.32) / 0.73));
+  if (t < 8.1) return -1.35;
+  if (t < 10.2) return lerp(-1.35, -0.06, easeInOutCubic((t - 8.1) / 2.1));
+  return -0.06;
+}
+
+function tiltOf(t, time) {
+  const sh = shakeAmt(t);
+  if (t >= T_RETURN && t < T_LAND) {
+    const u = (t - T_RETURN) / (T_LAND - T_RETURN);
+    return Math.sin(u * Math.PI * 2) * 0.014 * Math.sin(Math.PI * u);
+  }
+  if (sh > 0) return Math.sin(time * 48) * 0.0024 * sh;
+  return 0;
+}
+
+function makePuff(rgb, seed) {
+  const S = 128;
+  const c = document.createElement("canvas");
+  c.width = c.height = S;
+  const g = c.getContext("2d");
+  for (let i = 0; i < 7; i++) {
+    const ox = S * (0.32 + hash(seed + i * 1.7) * 0.36);
+    const oy = S * (0.32 + hash(seed + i * 2.9) * 0.36);
+    const rad = S * (0.2 + hash(seed + i * 4.1) * 0.2);
+    const rg = g.createRadialGradient(ox, oy, rad * 0.08, ox, oy, rad);
+    rg.addColorStop(0, "rgba(" + rgb + ",0.62)");
+    rg.addColorStop(0.42, "rgba(" + rgb + ",0.24)");
+    rg.addColorStop(1, "rgba(" + rgb + ",0)");
+    g.fillStyle = rg;
+    g.beginPath();
+    g.arc(ox, oy, rad, 0, Math.PI * 2);
+    g.fill();
+  }
+  return c;
+}
+
+function makeEmberSprite() {
+  const S = 32;
+  const c = document.createElement("canvas");
+  c.width = c.height = S;
+  const g = c.getContext("2d");
+  const rg = g.createRadialGradient(16, 16, 0, 16, 16, 16);
+  rg.addColorStop(0, "rgba(255,255,245,1)");
+  rg.addColorStop(0.28, "rgba(255,214,90,0.95)");
+  rg.addColorStop(0.6, "rgba(255,120,30,0.45)");
+  rg.addColorStop(1, "rgba(255,60,10,0)");
+  g.fillStyle = rg;
+  g.fillRect(0, 0, S, S);
+  return c;
+}
+
+function initPools() {
+  puffs.length = 0;
+  puffs.push(makePuff("255,246,232", 1.2));
+  puffs.push(makePuff("246,246,248", 2.4));
+  puffs.push(makePuff("198,200,206", 3.6));
+  puffs.push(makePuff("128,132,140", 4.8));
+  emberSprite = makeEmberSprite();
+  smoke.length = 0;
+  embers.length = 0;
+  for (let i = 0; i < SMOKE_N; i++) smoke.push({ alive: false });
+  for (let i = 0; i < EMBER_N; i++) embers.push({ alive: false });
+  hazeBuf = document.createElement("canvas");
+  hazeCtx = hazeBuf.getContext("2d");
+}
+
+function acquire(pool) {
+  for (let i = 0; i < pool.length; i++) if (!pool[i].alive) return pool[i];
+  let oldest = pool[0];
+  for (let i = 1; i < pool.length; i++) if (pool[i].life < oldest.life) oldest = pool[i];
+  return oldest;
+}
+
+function killAll() {
+  for (let i = 0; i < smoke.length; i++) smoke[i].alive = false;
+  for (let i = 0; i < embers.length; i++) embers[i].alive = false;
+  ripples.length = 0;
+  smokeAcc = trailAcc = emberAcc = ventAcc = rippleAcc = 0;
+}
+
+function spawnSmoke(opt) {
+  const p = acquire(smoke);
+  p.alive = true;
+  p.x = opt.x;
+  p.y = opt.y;
+  p.vx = opt.vx;
+  p.vy = opt.vy;
+  p.life = p.max = opt.life;
+  p.size = opt.size;
+  p.grow = opt.grow;
+  p.rot = Math.random() * Math.PI * 2;
+  p.vr = (Math.random() - 0.5) * opt.spin;
+  p.seed = Math.random() * 20;
+  p.baseA = opt.alpha;
+  p.kind = opt.kind;
+  p.front = opt.front;
+  p.warm = opt.warm;
+  p.stretch = opt.stretch;
+  p.buoy = opt.buoy;
+}
+
+function burstGround(env, n, intense) {
+  for (let i = 0; i < n; i++) spawnGround(env, intense);
+}
+
+function spawnGround(env, intense) {
+  const column = Math.random() < 0.22;
+  const side = Math.random() < 0.5 ? -1 : 1;
+  const trench = Math.random() < 0.55;
+  const x = trench ? env.padX + side * (env.halfW * 1.1 + Math.random() * 8) : env.padX + (Math.random() - 0.5) * 16;
+  spawnSmoke({
+    x: x,
+    y: env.padY + 2 + Math.random() * 8,
+    vx: column ? (Math.random() - 0.5) * 28 : side * (60 + Math.random() * 150) * (intense ? 1.25 : 1),
+    vy: column ? -70 - Math.random() * 50 : -12 - Math.random() * 34,
+    life: 3.4 + Math.random() * 3.1,
+    size: column ? 26 + Math.random() * 20 : 14 + Math.random() * 20,
+    grow: column ? 42 + Math.random() * 36 : 26 + Math.random() * 34,
+    spin: 0.5,
+    alpha: 0.28 + Math.random() * 0.22,
+    kind: "ground",
+    front: Math.random() < 0.34,
+    warm: Math.random() < (column ? 0.25 : 0.55),
+    stretch: column ? 0.85 + Math.random() * 0.25 : 1.25 + Math.random() * 0.55,
+    buoy: column ? -18 : -8
+  });
+}
+
+function spawnTrail(env, altK) {
+  const thin = 1 - altK * 0.72;
+  spawnSmoke({
+    x: env.nozzleX + (Math.random() - 0.5) * (8 + thin * 14),
+    y: env.nozzleY + Math.random() * 10,
+    vx: (Math.random() - 0.5) * 16,
+    vy: 10 + Math.random() * 36,
+    life: (0.9 + Math.random() * 1.5) * (0.65 + thin * 0.5),
+    size: (8 + Math.random() * 14) * (0.45 + thin * 0.55),
+    grow: 14 + Math.random() * 20,
+    spin: 0.8,
+    alpha: (0.22 + Math.random() * 0.2) * (0.4 + thin * 0.6),
+    kind: "trail",
+    front: false,
+    warm: Math.random() < 0.75,
+    stretch: 0.75 + Math.random() * 0.35,
+    buoy: -6
+  });
+}
+
+function spawnVent(env) {
+  const side = Math.random() < 0.5 ? -1 : 1;
+  spawnSmoke({
+    x: env.padX + side * env.halfW * 0.95,
+    y: env.padY - env.visH * (0.22 + Math.random() * 0.45),
+    vx: side * (6 + Math.random() * 14),
+    vy: -18 - Math.random() * 22,
+    life: 1.2 + Math.random() * 1.1,
+    size: 5 + Math.random() * 7,
+    grow: 9,
+    spin: 0.4,
+    alpha: 0.16,
+    kind: "trail",
+    front: false,
+    warm: false,
+    stretch: 1,
+    buoy: -10
+  });
+}
+
+function spawnEmber(env) {
+  const p = acquire(embers);
+  const side = Math.random() < 0.5 ? -1 : 1;
+  p.alive = true;
+  p.x = env.nozzleX + (Math.random() - 0.5) * env.halfW * 1.4;
+  p.y = env.nozzleY + 2;
+  p.vx = side * (30 + Math.random() * 170);
+  p.vy = -40 - Math.random() * 190;
+  p.grav = 220 + Math.random() * 80;
+  p.life = p.max = 0.28 + Math.random() * 0.55;
+  p.size = 1.6 + Math.random() * 2.8;
+}
+
+function updateParticles(dt, time, env, t) {
+  const altK = clamp(env.alt / (env.H * 0.55), 0, 1);
+  const thrust = thrustLevel(t, time);
+
+  if (t < 0.85) ventAcc += dt * 22 * (1 - t / 0.85);
+  if (t > 0.28 && t < 5.8) {
+    const ramp = clamp((t - 0.28) / 1.1, 0, 1);
+    const fade = t > 4.3 ? clamp(1 - (t - 4.3) / 1.5, 0, 1) : 1;
+    smokeAcc += dt * 120 * ramp * fade;
+  }
+  if (thrust > 0.05 && t < T_EXIT) {
+    trailAcc += dt * thrust * 150 * (1 - altK * 0.78);
+    emberAcc += dt * thrust * 80 * (1 - altK * 0.88);
+  }
+
+  while (ventAcc >= 1) { ventAcc -= 1; spawnVent(env); }
+  while (smokeAcc >= 1) { smokeAcc -= 1; spawnGround(env, t > 1.3 && t < 3.2); }
+  while (trailAcc >= 1) { trailAcc -= 1; spawnTrail(env, altK); }
+  while (emberAcc >= 1) { emberAcc -= 1; spawnEmber(env); }
+
+  if (prevT < 0.42 && t >= 0.42) burstGround(env, 28, false);
+  if (prevT < T_IGNITE && t >= T_IGNITE) burstGround(env, 48, true);
+
+  const wind = 18;
+  for (let i = 0; i < smoke.length; i++) {
+    const p = smoke[i];
+    if (!p.alive) continue;
+    p.life -= dt;
+    if (p.life <= 0) { p.alive = false; continue; }
+    p.vx += (Math.sin(time * 0.85 + p.seed) * 22 + wind * (p.kind === "ground" ? 0.35 : 0.15)) * dt;
+    p.vy += (Math.cos(time * 0.6 + p.seed * 1.4) * 12 + p.buoy) * dt;
+    if (p.kind === "ground") {
+      const dx = p.x - env.padX;
+      const risen = env.padY - p.y;
+      if (risen > 18 && risen < 260) p.vx += Math.sign(dx || (p.seed - 10)) * (16 + risen * 0.12) * dt;
+    }
+    p.vx *= 1 - 0.28 * dt;
+    p.vy *= 1 - 0.18 * dt;
+    p.x += p.vx * dt;
+    p.y += p.vy * dt;
+    p.size += p.grow * dt;
+    p.grow *= 1 - 0.42 * dt;
+    p.rot += p.vr * dt;
+  }
+
+  for (let i = 0; i < embers.length; i++) {
+    const p = embers[i];
+    if (!p.alive) continue;
+    p.life -= dt;
+    if (p.life <= 0) { p.alive = false; continue; }
+    p.vy += p.grav * dt;
+    p.x += p.vx * dt;
+    p.y += p.vy * dt;
+  }
+
+  const energy = seaEnergy(t);
+  if (energy > 0.15) rippleAcc += dt * (0.7 + energy * 1.4);
+  while (rippleAcc >= 1 && ripples.length < 12) {
+    rippleAcc -= 1;
+    const ang = Math.random() * Math.PI * 2;
+    ripples.push({
+      x: env.islandX + Math.cos(ang) * env.islandRx * (0.7 + Math.random() * 0.55),
+      y: env.islandY + Math.sin(ang) * env.islandRy * 0.85,
+      r: 8,
+      max: 70 + Math.random() * 110,
+      a: 0.28 + Math.random() * 0.15
+    });
+  }
+  let w = 0;
+  for (let i = 0; i < ripples.length; i++) {
+    const rp = ripples[i];
+    rp.r += dt * (36 + energy * 30);
+    rp.a -= dt * 0.16;
+    if (rp.a > 0 && rp.r < rp.max) ripples[w++] = rp;
+  }
+  ripples.length = w;
+
+  if (t >= T_RETURN) {
+    for (let i = 0; i < smoke.length; i++) smoke[i].alive = false;
+    for (let i = 0; i < embers.length; i++) embers[i].alive = false;
+  }
+}
+
+function layout(t) {
+  const padX0 = W * 0.5;
+  const padY = H * 0.735;
+  const rocketH = Math.max(260, Math.min(H * 0.5, W * 0.7));
+  const exitAlt = padY + 36;
+  const alt = altitude(t, exitAlt);
+  const sc = animScale(t, alt, exitAlt);
+  const drift = xDrift(t);
+  const visH = rocketH * sc;
+  const halfW = visH * 0.078;
+  return {
+    W: W,
+    H: H,
+    padX: padX0 + drift,
+    padX0: padX0,
+    padY: padY,
+    rocketH: rocketH,
+    visH: visH,
+    alt: alt,
+    sc: sc,
+    exitAlt: exitAlt,
+    halfW: halfW,
+    nozzleX: padX0 + drift,
+    nozzleY: padY - alt,
+    islandX: W * 0.5,
+    islandY: H * 0.8,
+    islandRx: Math.max(W * 0.26, halfW * 7),
+    islandRy: Math.max(H * 0.085, 48),
+    horizon: H * 0.6,
+    sunX: W * 0.22
+  };
+}
+
+function roundRect(g, x, y, w, h, r) {
+  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
+  g.beginPath();
+  g.moveTo(x + rr, y);
+  g.arcTo(x + w, y, x + w, y + h, rr);
+  g.arcTo(x + w, y + h, x, y + h, rr);
+  g.arcTo(x, y + h, x, y, rr);
+  g.arcTo(x, y, x + w, y, rr);
+  g.closePath();
+}
+
+function rebuildSky() {
+  skyCanvas = document.createElement("canvas");
+  skyCanvas.width = Math.max(1, Math.floor(W));
+  skyCanvas.height = Math.max(1, Math.floor(H));
+  skyCtx = skyCanvas.getContext("2d");
+  const g = skyCtx.createLinearGradient(0, 0, 0, H);
+  g.addColorStop(0, "#05060e");
+  g.addColorStop(0.16, "#0a1233");
+  g.addColorStop(0.34, "#16366f");
+  g.addColorStop(0.48, "#9a4068");
+  g.addColorStop(0.56, "#e36a4e");
+  g.addColorStop(0.63, "#f6a15a");
+  g.addColorStop(0.7, "#ffd0a4");
+  g.addColorStop(1, "#12384c");
+  skyCtx.fillStyle = g;
+  skyCtx.fillRect(0, 0, W, H);
+
+  const sunY = H * 0.6;
+  const sunR = Math.min(W, H) * 0.11;
+  const sg = skyCtx.createRadialGradient(W * 0.22, sunY, sunR * 0.2, W * 0.22, sunY, sunR * 3.1);
+  sg.addColorStop(0, "rgba(255,236,210,0.95)");
+  sg.addColorStop(0.18, "rgba(255,184,110,0.55)");
+  sg.addColorStop(0.45, "rgba(255,120,70,0.18)");
+  sg.addColorStop(1, "rgba(255,80,40,0)");
+  skyCtx.fillStyle = sg;
+  skyCtx.beginPath();
+  skyCtx.arc(W * 0.22, sunY, sunR * 3.1, 0, Math.PI * 2);
+  skyCtx.fill();
+
+  vignette = ctx.createRadialGradient(W * 0.5, H * 0.45, Math.min(W, H) * 0.25, W * 0.5, H * 0.5, Math.max(W, H) * 0.72);
+  vignette.addColorStop(0, "rgba(0,0,0,0)");
+  vignette.addColorStop(1, "rgba(0,0,0,0.38)");
+}
+
+function rebuildStars() {
+  stars = [];
+  const count = Math.floor(clamp((W * H) / 8500, 80, 260));
+  for (let i = 0; i < count; i++) {
+    stars.push({
+      x: Math.random() * W,
+      y: Math.random() * H * 0.5,
+      r: Math.random() < 0.07 ? 1.7 : 0.35 + Math.random() * 1.05,
+      p: Math.random() * Math.PI * 2,
+      s: 0.5 + Math.random() * 2.4,
+      a: 0.25 + Math.random() * 0.75
+    });
+  }
