+
+function drawOcean(time, env, energy) {
+  const horizon = env.horizon;
+  const g = ctx.createLinearGradient(0, horizon - 8, 0, H);
+  g.addColorStop(0, "#f0a07a");
+  g.addColorStop(0.07, "#1c6d8c");
+  g.addColorStop(0.28, "#0c4564");
+  g.addColorStop(0.6, "#082c44");
+  g.addColorStop(1, "#04141f");
+  ctx.fillStyle = g;
+  ctx.fillRect(0, horizon - 4, W, H - horizon + 4);
