+  const sunX = env.sunX;
+  for (let i = 0; i < 16; i++) {
+    const y = horizon + 10 + i * (H * 0.018);
+    const wob = Math.sin(time * 1.6 + i * 0.8) * (6 + i);
+    const w = (10 + i * 4.2) * (1 + energy * 0.15);
+    ctx.globalAlpha = 0.22 - i * 0.012;
+    ctx.fillStyle = i % 2 ? "#ffd2a4" : "#ffbf88";
