+    const amp = 2.4 + i * 0.35 + energy * (2.2 + i * 0.4);
+    const k = 0.010 + i * 0.0026;
+    const spd = time * (0.75 + i * 0.22);
+    ctx.beginPath();
+    for (let x = 0; x <= W; x += 8) {
