+
+function islandPath(cx, cy, rx, ry, bias) {
+  ctx.beginPath();
+  const steps = 72;
+  for (let i = 0; i <= steps; i++) {
+    const a = (i / steps) * Math.PI * 2;
+    const n = 1
+      + 0.07 * Math.sin(a * 3 + bias)
+      + 0.045 * Math.sin(a * 5 + 1.4)
+      + 0.03 * Math.sin(a * 2 - 0.6);
