+  ctx.lineTo(bw * 1.85, L * 0.975);
+  ctx.lineTo(bw * 0.15, yS1b);
+  ctx.closePath();
+  fg = ctx.createLinearGradient(bw, 0, bw * 2.2, 0);
+  fg.addColorStop(0, "#5c6570");
+  fg.addColorStop(0.5, "#f4f7fb");
+  fg.addColorStop(1, "#6d7580");
+  ctx.fillStyle = fg;
+  ctx.fill();
+  ctx.stroke();
+
+  ctx.beginPath();
+  ctx.moveTo(0, yS1b - L * 0.05);
+  ctx.lineTo(-bw * 0.28, L * 0.99);
+  ctx.lineTo(bw * 0.28, L * 0.99);
+  ctx.closePath();
+  ctx.fillStyle = "#3e4652";
+  ctx.fill();
+
+  ctx.beginPath();
+  ctx.moveTo(0, 4);
+  ctx.bezierCurveTo(bw * 0.2, yNose1 * 0.35, bw, yNose1 * 0.72, bw, yNose1);
+  ctx.lineTo(-bw, yNose1);
+  ctx.bezierCurveTo(-bw, yNose1 * 0.72, -bw * 0.2, yNose1 * 0.35, 0, 4);
+  ctx.closePath();
+  const ng = ctx.createLinearGradient(-bw, 0, bw, 0);
+  ng.addColorStop(0, "#1c212b");
+  ng.addColorStop(0.35, "#8d95a3");
+  ng.addColorStop(0.5, "#d5dbe6");
+  ng.addColorStop(0.72, "#3d4553");
+  ng.addColorStop(1, "#141820");
+  ctx.fillStyle = ng;
+  ctx.fill();
+  ctx.strokeStyle = "rgba(255,255,255,0.25)";
+  ctx.lineWidth = 0.8;
+  ctx.beginPath();
