+  ctx.stroke();
+
+  ctx.strokeStyle = "#d9dee8";
+  ctx.lineWidth = 1.4;
+  ctx.beginPath();
+  ctx.moveTo(0, 4);
+  ctx.lineTo(0, -L * 0.018);
+  ctx.stroke();
+  ctx.fillStyle = "#f2f5f8";
+  ctx.beginPath();
+  ctx.arc(0, -L * 0.02, Math.max(1.6, L * 0.006), 0, Math.PI * 2);
+  ctx.fill();
+
+  ctx.fillStyle = bodyGradient(-bw, bw);
+  ctx.fillRect(-bw, yNose1, bw * 2, yFair1 - yNose1);
+  panelLines(yNose1 + 4, yFair1 - 2, bw);
+  ctx.strokeStyle = "rgba(40,40,46,0.35)";
+  ctx.lineWidth = 1;
+  ctx.beginPath();
+  ctx.moveTo(0, yNose1 + 2);
+  ctx.lineTo(0, yFair1 - 2);
+  ctx.stroke();
+  ctx.strokeStyle = "rgba(20,20,24,0.45)";
+  ctx.beginPath();
+  ctx.moveTo(-bw, yNose1);
+  ctx.lineTo(bw, yNose1);
+  ctx.stroke();
+
+  ctx.fillStyle = "#9c3429";
+  ctx.fillRect(-bw, yFair1, bw * 2, yBand1 - yFair1);
+  ctx.fillStyle = "#e2b656";
+  ctx.fillRect(-bw, yFair1, bw * 2, 2);
+  ctx.fillRect(-bw, yBand1 - 2, bw * 2, 2);
+  drawEmblem(0, (yFair1 + yBand1) / 2, Math.min(bw * 0.55, (yBand1 - yFair1) * 0.38));
+
+  ctx.fillStyle = bodyGradient(-bw, bw);
+  ctx.fillRect(-bw, yBand1, bw * 2, yS2b - yBand1);
+  panelLines(yBand1 + 3, yS2b - 2, bw);
+  ctx.fillStyle = "#1a1c22";
+  ctx.fillRect(-bw, yBand1 + (yS2b - yBand1) * 0.22, bw * 2, Math.max(4, L * 0.012));
+  ctx.fillRect(-bw, yS2b - Math.max(5, L * 0.014), bw * 2, Math.max(5, L * 0.014));
+  drawFlag(-bw * 0.72, yBand1 + (yS2b - yBand1) * 0.38, bw * 0.7, L * 0.045);
+
+  ctx.fillStyle = "rgba(20,24,32,0.8)";
+  for (let i = 0; i < 3; i++) {
+    ctx.beginPath();
+    ctx.arc(bw * 0.55, yBand1 + 16 + i * 14, 1.5, 0, Math.PI * 2);
+    ctx.fill();
+  }
+
+  ctx.fillStyle = "#16181d";
+  ctx.fillRect(-bw, yS2b, bw * 2, yInt1 - yS2b);
+  ctx.strokeStyle = "rgba(200,206,216,0.28)";
+  ctx.lineWidth = 0.6;
+  const rows = 4;
+  for (let r = 1; r < rows; r++) {
+    const y = yS2b + ((yInt1 - yS2b) * r) / rows;
+    ctx.beginPath();
+    ctx.moveTo(-bw + 2, y);
+    ctx.lineTo(bw - 2, y);
+    ctx.stroke();
+  }
+  for (let c = -2; c <= 2; c++) {
+    ctx.beginPath();
+    ctx.moveTo((bw * c) / 3, yS2b + 2);
+    ctx.lineTo((bw * c) / 3, yInt1 - 2);
+    ctx.stroke();
+  }
+
+  ctx.fillStyle = bodyGradient(-bw, bw);
+  ctx.fillRect(-bw, yInt1, bw * 2, yS1b - yInt1);
+  panelLines(yInt1 + 4, yS1b - 4, bw);
+  ctx.fillStyle = "#1a1c22";
+  ctx.fillRect(-bw, yInt1 + L * 0.03, bw * 2, Math.max(5, L * 0.016));
+  ctx.fillRect(-bw, yS1b - L * 0.055, bw * 2, Math.max(6, L * 0.02));
+
+  const hatchY = yInt1 + (yS1b - yInt1) * 0.42;
+  const hatchW = bw * 0.62;
+  const hatchH = L * 0.055;
+  roundRect(ctx, -hatchW * 0.1, hatchY, hatchW, hatchH, 3);
+  ctx.fillStyle = "#ded8cc";
+  ctx.fill();
+  ctx.lineWidth = 1;
+  ctx.strokeStyle = "rgba(30,26,22,0.55)";
+  ctx.stroke();
+  ctx.strokeStyle = "rgba(40,36,30,0.65)";
+  ctx.beginPath();
+  ctx.moveTo(hatchW * 0.15, hatchY + hatchH * 0.5);
+  ctx.lineTo(hatchW * 0.42, hatchY + hatchH * 0.5);
+  ctx.moveTo(hatchW * 0.28, hatchY + hatchH * 0.28);
+  ctx.lineTo(hatchW * 0.28, hatchY + hatchH * 0.72);
+  ctx.stroke();
+  ctx.fillStyle = "rgba(50,40,30,0.55)";
+  const bolts = [[0, 0], [1, 0], [0, 1], [1, 1]];
+  for (let i = 0; i < bolts.length; i++) {
+    ctx.beginPath();
+    ctx.arc(-hatchW * 0.1 + 3 + bolts[i][0] * (hatchW - 6), hatchY + 3 + bolts[i][1] * (hatchH - 6), 0.9, 0, Math.PI * 2);
+    ctx.fill();
+  }
+
+  ctx.strokeStyle = "#2a2e36";
+  ctx.lineWidth = Math.max(2, bw * 0.09);
+  ctx.beginPath();
+  ctx.moveTo(bw * 0.72, yInt1 + 8);
+  ctx.lineTo(bw * 0.72, yS1b - 8);
+  ctx.stroke();
+  ctx.strokeStyle = "#3e4652";
+  ctx.lineWidth = 1;
+  for (let y = yInt1 + 16; y < yS1b - 10; y += 18) {
+    ctx.beginPath();
+    ctx.moveTo(bw * 0.62, y);
+    ctx.lineTo(bw * 0.84, y);
+    ctx.stroke();
+  }
+
+  ctx.fillStyle = "#14171c";
+  ctx.fillRect(-bw - 0.5, yS1b, bw * 2 + 1, ySkirt - yS1b);
+
+  ctx.strokeStyle = "rgba(20,16,12,0.25)";
+  ctx.lineWidth = 1;
+  ctx.strokeRect(-bw, yNose1, bw * 2, ySkirt - yNose1);
+
+  const bells = [
+    [-bw * 0.62, yBellTop, bw * 0.34],
+    [bw * 0.62, yBellTop, bw * 0.34],
+    [0, yBellTop + 1, bw * 0.3],
+    [-bw * 0.34, yBellTop + L * 0.012, bw * 0.4],
+    [bw * 0.34, yBellTop + L * 0.012, bw * 0.4],
+    [0, yBellTop + L * 0.02, bw * 0.46]
+  ];
+  for (let i = 0; i < bells.length; i++) drawBell(bells[i][0], bells[i][1], bells[i][2], thrust);
+}
+
+function flameBlob(len, w, rgba, phase, time) {
+  const wob = Math.sin(time * 36 + phase) * w * 0.12;
+  const lenJ = len * (0.92 + 0.08 * Math.sin(time * 52 + phase * 1.7));
+  const g = ctx.createLinearGradient(0, 0, 0, lenJ);
+  g.addColorStop(0, rgba);
+  g.addColorStop(0.55, rgba);
+  g.addColorStop(1, "rgba(255,80,20,0)");
+  ctx.fillStyle = g;
+  ctx.beginPath();
+  ctx.moveTo(0, 0);
+  ctx.bezierCurveTo(w + wob, lenJ * 0.18, w * 0.72 - wob, lenJ * 0.62, wob * 0.4, lenJ);
+  ctx.bezierCurveTo(-w * 0.72 + wob, lenJ * 0.62, -w - wob, lenJ * 0.18, 0, 0);
+  ctx.fill();
+}
+
+function drawFlame(env, thrust, time) {
+  if (thrust < 0.03) return;
+  const climb = clamp(env.alt / (env.H * 0.45), 0, 1);
+  const L = env.visH;
+  const flick = 0.78 + 0.22 * (0.5 + 0.5 * Math.sin(time * 61)) * (0.5 + 0.5 * noise(time * 33));
+  const len = L * (0.16 + thrust * 0.42) * (1 + climb * 2.05) * flick;
+  const w = Math.max(8, env.halfW * 0.55) * (0.85 + thrust * 0.4);
+
+  ctx.save();
+  ctx.translate(env.nozzleX, env.nozzleY - 2);
+  ctx.globalCompositeOperation = "lighter";
+  flameBlob(len * 1.25, w * 2.5, "rgba(255,50,24,0.16)", 0.4, time);
+  flameBlob(len * 1.02, w * 1.75, "rgba(255,110,28,0.32)", 1.2, time);
+  flameBlob(len * 0.74, w * 1.05, "rgba(255,176,48,0.62)", 2.1, time);
+  flameBlob(len * 0.46, w * 0.48, "rgba(255,246,220,0.9)", 2.8, time);
+  ctx.save();
+  ctx.translate(-w * 0.85, 2);
+  flameBlob(len * 0.5, w * 0.38, "rgba(255,140,36,0.5)", 4, time);
+  ctx.restore();
+  ctx.save();
+  ctx.translate(w * 0.85, 2);
+  flameBlob(len * 0.48, w * 0.36, "rgba(255,140,36,0.5)", 5.2, time);
+  ctx.restore();
+  ctx.restore();
+}
+
+function drawGlow(env, t) {
+  const gnd = padGlowAmt(t);
+  const thrust = thrustLevel(t, t);
+  if (gnd < 0.02 && thrust < 0.02) return;
+  ctx.save();
+  ctx.globalCompositeOperation = "lighter";
+  if (gnd > 0.02) {
+    const rad = env.rocketH * (0.28 + gnd * 0.45);
+    const g = ctx.createRadialGradient(env.padX0, env.padY, 4, env.padX0, env.padY, rad);
+    g.addColorStop(0, "rgba(255,214,140," + (0.45 * gnd) + ")");
+    g.addColorStop(0.35, "rgba(255,120,40," + (0.22 * gnd) + ")");
+    g.addColorStop(1, "rgba(255,80,20,0)");
+    ctx.fillStyle = g;
+    ctx.beginPath();
+    ctx.arc(env.padX0, env.padY, rad, 0, Math.PI * 2);
+    ctx.fill();
+  }
+  if (thrust > 0.05) {
+    const rad = env.visH * 0.45 * thrust;
+    const g = ctx.createRadialGradient(env.nozzleX, env.nozzleY, 2, env.nozzleX, env.nozzleY, rad);
+    g.addColorStop(0, "rgba(255,230,190," + (0.55 * thrust) + ")");
+    g.addColorStop(0.4, "rgba(255,140,40," + (0.2 * thrust) + ")");
+    g.addColorStop(1, "rgba(255,80,20,0)");
+    ctx.fillStyle = g;
+    ctx.beginPath();
+    ctx.arc(env.nozzleX, env.nozzleY, rad, 0, Math.PI * 2);
+    ctx.fill();
+  }
+  ctx.restore();
+}
+
+function drawShock(env, t) {
+  if (t < 1.42 || t > 3.3) return;
+  const u = (t - 1.42) / 1.88;
+  const r = 16 + u * Math.min(W, H) * 0.28;
+  ctx.beginPath();
+  ctx.ellipse(env.padX0, env.padY + 4, r, r * 0.22, 0, 0, Math.PI * 2);
+  ctx.strokeStyle = "rgba(255,226,196," + ((1 - u) * 0.5) + ")";
+  ctx.lineWidth = 2;
+  ctx.stroke();
+  ctx.beginPath();
+  ctx.ellipse(env.padX0, env.padY + 6, r * 0.72, r * 0.16, 0, 0, Math.PI * 2);
+  ctx.strokeStyle = "rgba(255,255,255," + ((1 - u) * 0.25) + ")";
+  ctx.stroke();
+}
+
+function applyHeatHaze(x, y, w, h, time, strength) {
+  if (strength < 0.08 || w < 4 || h < 4) return;
+  const hx = clamp(x, 0, W - 2);
+  const hy = clamp(y, 0, H - 2);
+  const sw = Math.min(Math.ceil(w), Math.floor(W - hx));
+  const sh = Math.min(Math.ceil(h), Math.floor(H - hy));
+  if (sw < 4 || sh < 4) return;
+  if (hazeBuf.width < sw || hazeBuf.height < sh) {
+    hazeBuf.width = Math.max(hazeBuf.width, sw);
+    hazeBuf.height = Math.max(hazeBuf.height, sh);
+  }
+  hazeCtx.clearRect(0, 0, sw, sh);
+  hazeCtx.drawImage(canvas, hx * dpr, hy * dpr, sw * dpr, sh * dpr, 0, 0, sw, sh);
+  const amp = 2.2 + strength * 3.4;
+  for (let i = 0; i < sh; i += 2) {
+    const ox = Math.sin(i * 0.38 + time * 22) * amp + Math.sin(i * 0.11 - time * 13) * amp * 0.45;
+    ctx.drawImage(hazeBuf, 0, i, sw, 2, hx + ox, hy + i, sw, 2);
+  }
+}
+
+function smokeFade(t) {
+  if (t < 8) return 1;
+  if (t < T_RETURN) return 1 - (t - 8) / (T_RETURN - 8);
+  return 0;
+}
+
+function drawSmoke(time, t, front) {
+  const fade = smokeFade(t);
+  if (fade <= 0) return;
+  for (let i = 0; i < smoke.length; i++) {
+    const p = smoke[i];
+    if (!p.alive || p.front !== front) continue;
+    const age = 1 - p.life / p.max;
+    const fadeIn = clamp(age / 0.08, 0, 1);
+    const fadeOut = Math.pow(clamp(1 - age, 0, 1), 1.25);
+    const idx = p.warm && age < 0.32 ? 0 : age < 0.22 ? 1 : age < 0.58 ? 2 : 3;
+    ctx.globalAlpha = fadeIn * fadeOut * p.baseA * fade;
+    const s = p.size;
+    ctx.save();
+    ctx.translate(p.x, p.y);
+    ctx.rotate(p.rot);
+    ctx.scale(p.stretch, 1);
+    ctx.drawImage(puffs[idx], -s / 2, -s / 2, s, s);
+    ctx.restore();
+  }
+  ctx.globalAlpha = 1;
+}
+
+function drawEmbers() {
+  ctx.save();
+  ctx.globalCompositeOperation = "lighter";
+  ctx.lineCap = "round";
+  for (let i = 0; i < embers.length; i++) {
+    const p = embers[i];
+    if (!p.alive) continue;
+    const age = 1 - p.life / p.max;
+    const a = (1 - age) * (0.45 + 0.55 * (1 - age));
+    ctx.globalAlpha = a;
+    const s = p.size * (1 + age);
+    ctx.drawImage(emberSprite, p.x - s, p.y - s, s * 2, s * 2);
+    ctx.strokeStyle = "rgba(255,210,120," + a + ")";
+    ctx.lineWidth = 1.2;
+    ctx.beginPath();
+    ctx.moveTo(p.x, p.y);
+    ctx.lineTo(p.x - p.vx * 0.035, p.y - p.vy * 0.035);
+    ctx.stroke();
+  }
+  ctx.restore();
+}
+
+function drawRipples() {
+  for (let i = 0; i < ripples.length; i++) {
+    const rp = ripples[i];
+    ctx.beginPath();
+    ctx.ellipse(rp.x, rp.y, rp.r, rp.r * 0.32, 0, 0, Math.PI * 2);
+    ctx.strokeStyle = "rgba(214,242,246," + rp.a + ")";
+    ctx.lineWidth = 1.3;
+    ctx.stroke();
+  }
+}
+
+function drawShadow(env) {
+  const near = clamp(1 - env.alt / 80, 0, 1) * (env.sc > 0.9 ? 1 : env.sc);
+  if (near < 0.04 || env.alt > 90) return;
+  ctx.save();
+  ctx.translate(env.nozzleX, env.padY + 3);
+  ctx.scale(1, 0.28);
+  ctx.globalAlpha = 0.32 * near;
+  ctx.fillStyle = "#000";
+  ctx.beginPath();
+  ctx.ellipse(0, 0, env.halfW * 1.5, env.halfW * 1.5, 0, 0, Math.PI * 2);
+  ctx.fill();
+  ctx.restore();
+}
+
+function draw(t, time) {
+  const env = layout(t);
+  const thrust = thrustLevel(t, time);
+  const shake = shakeAmt(t);
+  const sx = Math.sin(time * 53) * shake + Math.sin(time * 97) * shake * 0.45;
+  const sy = Math.cos(time * 61) * shake * 0.85;
+
+  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+  ctx.clearRect(0, 0, W, H);
+  ctx.translate(sx, sy);
+
+  ctx.drawImage(skyCanvas, 0, 0, W, H);
+  drawStars(time);
+  drawClouds(time);
+  drawBirds(time);
+  drawOcean(time, env, seaEnergy(t));
+  drawRipples();
+  drawIsland(env, time);
+
+  const palmS = clamp(env.rocketH / 520, 0.75, 1.45);
+  drawPalm(env.islandX - env.islandRx * 0.62, env.islandY + env.islandRy * 0.05, palmS * 1.05, 0.4, time);
+  drawPalm(env.islandX + env.islandRx * 0.58, env.islandY - env.islandRy * 0.05, palmS * 0.92, 2.1, time);
+  drawPalm(env.islandX - env.islandRx * 0.22, env.islandY - env.islandRy * 0.35, palmS * 0.78, 3.4, time);
+
+  drawBlockhouse(env);
+  drawPad(env, t);
+  drawTower(env, time);
+  drawShadow(env);
+
+  drawSmoke(time, t, false);
+  drawGlow(env, t);
+  const hazeH = 36 + thrust * Math.min(130, env.visH * 0.34);
+  applyHeatHaze(env.nozzleX - 78, env.nozzleY - 6, 156, hazeH, time, thrust);
+  drawShock(env, t);
+  drawFlame(env, thrust, time);
+
+  if (env.nozzleY < H + 40 && env.nozzleY - env.visH > -env.visH - 80) {
+    ctx.save();
+    ctx.translate(env.nozzleX, env.nozzleY);
+    ctx.rotate(tiltOf(t, time));
+    ctx.translate(0, -env.visH);
+    drawRocket(env.visH, thrust);
+    ctx.restore();
+  }
+
+  drawEmbers();
+  drawSmoke(time, t, true);
+
+  ctx.fillStyle = vignette;
+  ctx.fillRect(-20, -20, W + 40, H + 40);
+  ctx.globalAlpha = 1;
+  ctx.globalCompositeOperation = "source-over";
+}
+
+let last = performance.now();
+function frame(now) {
+  const dt = Math.min(0.033, (now - last) / 1000);
+  last = now;
+  const time = now / 1000;
+  const t = time % CYCLE;
+  if (t < prevT) killAll();
+  const env = layout(t);
+  updateParticles(dt, time, env, t);
+  draw(t, time);
+  prevT = t;
+  requestAnimationFrame(frame);
+}
+
+initPools();
+resize();
+window.addEventListener("resize", resize);
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

