function applyHeatHaze(x, y, w, h, time, strength, sx, sy) {
  if (strength < 0.08 || w < 4 || h < 4) return;
  const hx = clamp(x, 0, W - 2);
  const hy = clamp(y, 0, H - 2);
  const sw = Math.min(Math.ceil(w), Math.floor(W - hx));
  const sh = Math.min(Math.ceil(h), Math.floor(H - hy));
  if (sw < 4 || sh < 4) return;
  if (hazeBuf.width < sw || hazeBuf.height < sh) {
    hazeBuf.width = Math.max(hazeBuf.width, sw);
    hazeBuf.height = Math.max(hazeBuf.height, sh);
  }
  const srcX = (hx + sx) * dpr;
  const srcY = (hy + sy) * dpr;
  hazeCtx.clearRect(0, 0, sw, sh);
  hazeCtx.drawImage(canvas, srcX, srcY, sw * dpr, sh * dpr, 0, 0, sw, sh);
  const amp = 2.2 + strength * 3.4;
  for (let i = 0; i < sh; i += 2) {
    const ox = Math.sin(i * 0.38 + time * 22) * amp + Math.sin(i * 0.11 - time * 13) * amp * 0.45;
    ctx.drawImage(hazeBuf, 0, i, sw, 2, hx + ox, hy + i, sw, 2);
  }
}

