function drawPad(env, t) {
  const x = env.padX0;
  const y = env.padY;
  const rw = Math.max(70, env.rocketH * 0.22);
  const scorch = scorchAmt(t);
  const deckY = y + rw * 0.34;

  ctx.save();
  ctx.translate(x, deckY + 8);
  ctx.scale(1, 0.42);
  ctx.beginPath();
  ctx.ellipse(0, 0, rw * 1.35, rw * 1.35, 0, 0, Math.PI * 2);
  ctx.fillStyle = "#6d6458";
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(x, deckY);
  ctx.scale(1, 0.4);
  ctx.beginPath();
  ctx.ellipse(0, 0, rw, rw, 0, 0, Math.PI * 2);
  const cg = ctx.createRadialGradient(0, 0, rw * 0.1, 0, 0, rw);
  cg.addColorStop(0, scorch > 0 ? lerpColor(scorch, "#8d867c", "#5a4036") : "#8a8378");
  cg.addColorStop(0.55, "#6e675e");
  cg.addColorStop(1, "#4e4943");
  ctx.fillStyle = cg;
  ctx.fill();
  ctx.lineWidth = 8;
  ctx.strokeStyle = "#d8a31a";
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.strokeStyle = "#1b1b1b";
  ctx.beginPath();
  ctx.ellipse(0, 0, rw * 0.86, rw * 0.86, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();

  ctx.fillStyle = "#2a241e";
  roundRect(ctx, x - rw * 0.28, y - 2, rw * 0.56, 16, 2);
  ctx.fill();

  if (scorch > 0.05) {
    ctx.save();
    ctx.globalAlpha = 0.45 * scorch;
    ctx.translate(x, y + 4);
    ctx.scale(1, 0.38);
    const sg = ctx.createRadialGradient(0, 0, 4, 0, 0, rw * 0.55);
    sg.addColorStop(0, "rgba(20,12,8,0.9)");
    sg.addColorStop(1, "rgba(20,12,8,0)");
    ctx.fillStyle = sg;
    ctx.beginPath();
    ctx.arc(0, 0, rw * 0.55, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

function lerpColor(u, a, b) {
  return u < 0.5 ? a : b;
}

function drawBlockhouse(env) {
  const s = clamp(env.rocketH / 430, 0.7, 1.3);
  const x = env.padX0 - env.rocketH * 0.34;
  const y = env.padY + 4;
  ctx.fillStyle = "#6a5f52";
  ctx.fillRect(x, y - 26 * s, 58 * s, 26 * s);
  ctx.fillStyle = "#8c7f6c";
  ctx.fillRect(x - 2 * s, y - 32 * s, 62 * s, 8 * s);
  ctx.fillStyle = "#2e2924";

