dev-browser <<'EOF'
const page = await browser.getPage("rocket");
await page.setViewportSize({ width: 1280, height: 800 });
await page.goto("file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/rocket-launch/2026-09-21-cursor-agent-grok-4-7-high/index.html");
const marks = [0.6, 2.4, 5.0, 7.2, 9.5, 12.4, 14.2, 16.2, 17.4];
let elapsed = 0;
const out = [];
for (const mark of marks) {
  const wait = Math.max(0, (mark - elapsed) * 1000);
  await page.waitForTimeout(wait);
  elapsed = mark;
  const info = await page.evaluate(() => {
    const c = document.querySelector("canvas");
    const g = c.getContext("2d");
    const w = c.width, h = c.height;
    const x0 = Math.floor(w * 0.48);
    const span = Math.floor(w * 0.08);
    const img = g.getImageData(x0, 0, span, h).data;
    let top = -1, bot = -1, white = 0, hot = 0;
    for (let y = 0; y < h; y += 3) {
      for (let x = 0; x < span; x += 3) {
        const i = (y * span + x) * 4;
        const r = img[i], gg = img[i+1], b = img[i+2];
        if (r > 215 && gg > 205 && b > 185 && (r - b) < 45) {
          white++;
          if (top < 0) top = y;
          bot = y;
        }
        if (r > 220 && gg > 120 && gg < 210 && b < 90) hot++;
      }
    }
    return { top, bot, white, hot, h, w };
  });
  out.push({ t: mark, ...info });
}
console.log(JSON.stringify(out, null, 2));
EOF

